// ACME Directory URLs
const STAGING_DIRECTORY = 'https://acme-staging-v02.api.letsencrypt.org/directory';
const PRODUCTION_DIRECTORY = 'https://acme-v02.api.letsencrypt.org/directory';

// Use staging for testing (change to PRODUCTION_DIRECTORY when ready)
const DIRECTORY_URL = STAGING_DIRECTORY;

// Get input data
const input = $input.first().json.body;
const email = input.email;
const domains = input.domains.filter(d => d && d.trim() !== '');
const certificateType = input.certificateType;

if (!email || domains.length === 0) {
  throw new Error('Email and at least one domain are required');
}

// Generate RSA key pair for account (in production, store and reuse this)
const crypto = require('crypto');

// Generate account key pair
const { privateKey: accountPrivateKey, publicKey: accountPublicKey } = crypto.generateKeyPairSync('rsa', {
  modulusLength: 2048,
  publicKeyEncoding: { type: 'spki', format: 'pem' },
  privateKeyEncoding: { type: 'pkcs8', format: 'pem' }
});

// Generate domain key pair (for CSR)
const { privateKey: domainPrivateKey, publicKey: domainPublicKey } = crypto.generateKeyPairSync('rsa', {
  modulusLength: 2048,
  publicKeyEncoding: { type: 'spki', format: 'pem' },
  privateKeyEncoding: { type: 'pkcs8', format: 'pem' }
});

// Base64URL encode function
function base64url(buffer) {
  return buffer.toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=/g, '');
}

// Get JWK from public key
function getJwk(publicKeyPem) {
  const publicKeyDer = crypto.createPublicKey(publicKeyPem).export({ type: 'spki', format: 'der' });
  // Parse the RSA public key
  const keyObject = crypto.createPublicKey(publicKeyPem);
  const jwk = keyObject.export({ format: 'jwk' });
  return {
    kty: 'RSA',
    n: jwk.n,
    e: jwk.e
  };
}

// Generate thumbprint for key
function getThumbprint(jwk) {
  const ordered = JSON.stringify({ e: jwk.e, kty: jwk.kty, n: jwk.n });
  const hash = crypto.createHash('sha256').update(ordered).digest();
  return base64url(hash);
}

const jwk = getJwk(accountPublicKey);
const thumbprint = getThumbprint(jwk);

// Store for next step
return {
  json: {
    directoryUrl: DIRECTORY_URL,
    email: email,
    domains: domains,
    certificateType: certificateType,
    accountPrivateKey: accountPrivateKey,
    accountPublicKey: accountPublicKey,
    domainPrivateKey: domainPrivateKey,
    jwk: jwk,
    thumbprint: thumbprint
  }
};

const input = $input.first().json;
const prevData = $('Generate Keys').first().json;

// Extract directory URLs
const directory = {
  newNonce: input.newNonce,
  newAccount: input.newAccount,
  newOrder: input.newOrder,
  revokeCert: input.revokeCert,
  keyChange: input.keyChange
};

return {
  json: {
    ...prevData,
    directory: directory
  }
};

const crypto = require('crypto');
const input = $input.first();
const prevData = $('Parse Directory').first().json;
const nonce = input.headers['replay-nonce'];

// Base64URL encode function
function base64url(input) {
  if (typeof input === 'string') {
    input = Buffer.from(input);
  }
  return input.toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=/g, '');
}

// Sign JWS
function signJws(payload, privateKeyPem, url, nonce, jwk) {
  const header = {
    alg: 'RS256',
    jwk: jwk,
    nonce: nonce,
    url: url
  };

  const encodedHeader = base64url(JSON.stringify(header));
  const encodedPayload = payload === '' ? '' : base64url(JSON.stringify(payload));
  const signatureInput = `${encodedHeader}.${encodedPayload}`;

  const sign = crypto.createSign('RSA-SHA256');
  sign.update(signatureInput);
  const signature = sign.sign(privateKeyPem);

  return {
    protected: encodedHeader,
    payload: encodedPayload,
    signature: base64url(signature)
  };
}

// Create account request
const accountPayload = {
  termsOfServiceAgreed: true,
  contact: [`mailto:${prevData.email}`]
};

const accountJws = signJws(
  accountPayload,
  prevData.accountPrivateKey,
  prevData.directory.newAccount,
  nonce,
  prevData.jwk
);

return {
  json: {
    ...prevData,
    nonce: nonce,
    accountJws: accountJws
  }
};

const crypto = require('crypto');
const input = $input.first().json;
const prevData = $('Prepare Account Request').first().json;

// Get new nonce from response
const newNonce = input.headers['replay-nonce'];
const accountUrl = input.headers['location'];

// Base64URL encode function
function base64url(input) {
  if (typeof input === 'string') {
    input = Buffer.from(input);
  }
  return input.toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=/g, '');
}

// Sign JWS with kid instead of jwk
function signJwsWithKid(payload, privateKeyPem, url, nonce, kid) {
  const header = {
    alg: 'RS256',
    kid: kid,
    nonce: nonce,
    url: url
  };

  const encodedHeader = base64url(JSON.stringify(header));
  const encodedPayload = payload === '' ? '' : base64url(JSON.stringify(payload));
  const signatureInput = `${encodedHeader}.${encodedPayload}`;

  const sign = crypto.createSign('RSA-SHA256');
  sign.update(signatureInput);
  const signature = sign.sign(privateKeyPem);

  return {
    protected: encodedHeader,
    payload: encodedPayload,
    signature: base64url(signature)
  };
}

// Build identifiers for order
const identifiers = prevData.domains.map(domain => ({
  type: 'dns',
  value: domain.startsWith('*.') ? domain.substring(2) : domain
}));

// For wildcard, we need to include the wildcard identifier
const orderIdentifiers = prevData.domains.map(domain => ({
  type: 'dns',
  value: domain
}));

// Create order request
const orderPayload = {
  identifiers: orderIdentifiers
};

const orderJws = signJwsWithKid(
  orderPayload,
  prevData.accountPrivateKey,
  prevData.directory.newOrder,
  newNonce,
  accountUrl
);

return {
  json: {
    ...prevData,
    accountUrl: accountUrl,
    nonce: newNonce,
    orderJws: orderJws
  }
};

const crypto = require('crypto');
const input = $input.first().json;
const prevData = $('Prepare Order').first().json;

// Order data
const orderUrl = input.headers['location'];
const orderBody = input.body;
const newNonce = input.headers['replay-nonce'];

// We need to fetch authorizations to get the challenges
// Store all data for the next step
return {
  json: {
    ...prevData,
    orderUrl: orderUrl,
    order: orderBody,
    authorizations: orderBody.authorizations,
    finalizeUrl: orderBody.finalize,
    nonce: newNonce
  }
};

const crypto = require('crypto');
const prevData = $('Parse Order').first().json;

// Base64URL encode function
function base64url(input) {
  if (typeof input === 'string') {
    input = Buffer.from(input);
  }
  return input.toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=/g, '');
}

// Sign JWS with kid
function signJwsWithKid(payload, privateKeyPem, url, nonce, kid) {
  const header = {
    alg: 'RS256',
    kid: kid,
    nonce: nonce,
    url: url
  };

  const encodedHeader = base64url(JSON.stringify(header));
  const encodedPayload = payload === '' ? '' : base64url(JSON.stringify(payload));
  const signatureInput = `${encodedHeader}.${encodedPayload}`;

  const sign = crypto.createSign('RSA-SHA256');
  sign.update(signatureInput);
  const signature = sign.sign(privateKeyPem);

  return {
    protected: encodedHeader,
    payload: encodedPayload,
    signature: base64url(signature)
  };
}

// Create request for each authorization
const authRequests = prevData.authorizations.map((authUrl, index) => {
  const jws = signJwsWithKid(
    '',
    prevData.accountPrivateKey,
    authUrl,
    prevData.nonce,
    prevData.accountUrl
  );

  return {
    authUrl: authUrl,
    jws: jws,
    index: index
  };
});

return authRequests.map(req => ({
  json: {
    ...prevData,
    currentAuth: req
  }
}));

const crypto = require('crypto');
const inputs = $input.all();
const prevData = $('Prepare Auth Requests').first().json;

// Base64URL encode function
function base64url(input) {
  if (typeof input === 'string') {
    input = Buffer.from(input);
  }
  return input.toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=/g, '');
}

// Process all authorizations and extract DNS challenges
const dnsRecords = [];
const challenges = [];

for (const item of inputs) {
  const authData = item.json.body;
  const identifier = authData.identifier;

  // Find DNS-01 challenge
  const dnsChallenge = authData.challenges.find(c => c.type === 'dns-01');

  if (dnsChallenge) {
    // Calculate the key authorization
    const keyAuthz = `${dnsChallenge.token}.${prevData.thumbprint}`;

    // SHA256 hash and base64url encode
    const hash = crypto.createHash('sha256').update(keyAuthz).digest();
    const txtValue = base64url(hash);

    // Build DNS record name
    const recordName = `_acme-challenge.${identifier.value}`;

    dnsRecords.push({
      name: recordName,
      value: txtValue,
      domain: identifier.value
    });

    challenges.push({
      url: dnsChallenge.url,
      token: dnsChallenge.token,
      keyAuthorization: keyAuthz,
      domain: identifier.value
    });
  }
}

// Prepare data to store for the next workflow
const orderData = {
  accountPrivateKey: prevData.accountPrivateKey,
  accountUrl: prevData.accountUrl,
  domainPrivateKey: prevData.domainPrivateKey,
  orderUrl: prevData.orderUrl,
  finalizeUrl: prevData.finalizeUrl,
  challenges: challenges,
  thumbprint: prevData.thumbprint,
  directory: prevData.directory
};

return {
  json: {
    dnsRecords: dnsRecords,
    orderData: Buffer.from(JSON.stringify(orderData)).toString('base64')
  }
};
